import CryptoKit
import Foundation
import XCTest
@testable import BridgeyMac

/// A session recorded between two Bridgey session clients (rust/client, the core of the Windows app) after pairing:
/// battery both ways, find device, one file in binary frames (files_fast_draft1) and one in JSON chunks. Every frame is
/// opened with this app's own decoder, envelope tags, fast frame code and AES-GCM, and both files are reassembled: what
/// the Mac would do with the same bytes. Generated by rust/client/src/vectors.rs.
final class SessionClientFilesVectorTests: XCTestCase {
    private struct Frame {
        let from: String
        let message: PairingMessage?
        let binary: Data?
    }

    private struct Vector {
        let sessionKey: Data
        let frames: [Frame]
        let files: [[String: Any]]
        let battery: [String: [String: Any]]
        let ids: [String: String]
    }

    private func load() throws -> Vector {
        let url = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .appendingPathComponent("../../../protocol/test-vectors/session-client-files-v1.json")
            .standardizedFileURL
        let object = try XCTUnwrap(try JSONSerialization.jsonObject(with: Data(contentsOf: url)) as? [String: Any])
        var frames: [Frame] = []
        var ids: [String: String] = [:]
        for raw in try XCTUnwrap(object["frames"] as? [[String: Any]]) {
            let from = try XCTUnwrap(raw["from"] as? String)
            if let line = raw["line"] as? String {
                let message = try decodeProtocolMessage(Data(line.utf8))
                if message.kind == "pairing.offer" || message.kind == "pairing.answer" { ids[from] = message.deviceId }
                frames.append(Frame(from: from, message: message, binary: nil))
            } else {
                let bytes = try XCTUnwrap(Data(base64Encoded: try XCTUnwrap(raw["binaryBase64"] as? String)))
                frames.append(Frame(from: from, message: nil, binary: bytes))
            }
        }
        return Vector(
            sessionKey: try XCTUnwrap(Data(base64Encoded: try XCTUnwrap(object["sessionKey"] as? String))),
            frames: frames,
            files: try XCTUnwrap(object["files"] as? [[String: Any]]),
            battery: try XCTUnwrap(object["battery"] as? [String: [String: Any]]),
            ids: ids
        )
    }

    private func open(_ message: PairingMessage, _ key: Data) throws -> Data {
        try decrypt(nonce: try XCTUnwrap(message.nonce), ciphertext: try XCTUnwrap(message.ciphertext), key: key)
    }

    func testEveryJsonFrameIsTaggedByItsSenderAndOpens() throws {
        let vector = try load()
        let envelopeKey = SessionSecurity.envelopeKey(sessionKey: vector.sessionKey)
        var kinds = Set<String>()
        for frame in vector.frames {
            guard let message = frame.message, !message.kind.hasPrefix("pairing.") else { continue }
            let sender = try XCTUnwrap(vector.ids[frame.from])
            XCTAssertTrue(SessionSecurity.tagMatches(envelopeKey: envelopeKey, senderDeviceID: sender, message: message), message.kind)
            if message.ciphertext != nil { XCTAssertNoThrow(try open(message, vector.sessionKey), message.kind) }
            kinds.insert(message.kind)
        }
        for kind in ["battery.update", "find.start", "find.started", "find.stopped", "files.offer", "files.accept", "files.chunk",
                     "files.chunk.ack", "files.complete", "files.complete.ack"] {
            XCTAssertTrue(kinds.contains(kind), kind)
        }
    }

    func testBatteryAndFindPayloadsAreWhatTheMacTakes() throws {
        let vector = try load()
        for frame in vector.frames {
            guard let message = frame.message, message.ciphertext != nil else { continue }
            switch message.kind {
            case "battery.update":
                let payload = try XCTUnwrap(try JSONSerialization.jsonObject(with: try open(message, vector.sessionKey)) as? [String: Any])
                let expected = try XCTUnwrap(vector.battery[frame.from])
                XCTAssertEqual(payload["level"] as? Int, expected["level"] as? Int)
                XCTAssertEqual(payload["isCharging"] as? Bool, expected["isCharging"] as? Bool)
            case "find.start", "find.started", "find.stopped":
                let payload = try XCTUnwrap(try JSONSerialization.jsonObject(with: try open(message, vector.sessionKey)) as? [String: Any])
                XCTAssertEqual(payload["alertId"] as? String, "active")
            default:
                break
            }
        }
    }

    func testBothFilesReassembleFromBinaryFramesAndJsonChunks() throws {
        let vector = try load()
        let frameKey = SessionSecurity.fastFrameKey(sessionKey: vector.sessionKey)
        var offers: [String: FileOfferPayload] = [:]
        var completes: [String: String] = [:]
        var chunks: [String: [(sequence: Int64, data: Data, binary: Bool)]] = [:]
        for frame in vector.frames {
            if let bytes = frame.binary {
                XCTAssertEqual(bytes.first, FastFrame.marker)
                let declared = bytes[2..<6].reduce(0) { $0 << 8 | Int($1) }
                XCTAssertEqual(declared, bytes.count - FastFrame.headerBytes)
                let payload = try openFastFrameBody(kind: bytes[1], body: bytes.subdata(in: FastFrame.headerBytes..<bytes.count),
                                                    key: frameKey, sender: try XCTUnwrap(vector.ids[frame.from]))
                XCTAssertEqual(payload.kind, FastFrame.chunkKind)
                chunks[payload.id, default: []].append((payload.sequence, payload.plaintext, true))
                continue
            }
            guard let message = frame.message else { continue }
            switch message.kind {
            case "files.offer":
                // The Mac's own payload type and the checks it makes before accepting.
                let offer = try JSONDecoder().decode(FileOfferPayload.self, from: try open(message, vector.sessionKey))
                XCTAssertNotNil(UUID(uuidString: offer.transferId))
                XCTAssertEqual(offer.transferId, message.transferId)
                XCTAssertFalse(offer.name.isEmpty)
                XCTAssertGreaterThanOrEqual(offer.size, 0)
                XCTAssertEqual(Data(base64Encoded: offer.sha256)?.count, 32)
                offers[offer.transferId] = offer
            case "files.chunk":
                XCTAssertNotNil(message.messageId, "the Mac takes a JSON chunk only with its own messageId")
                chunks[try XCTUnwrap(message.transferId), default: []].append((try XCTUnwrap(message.sequence), try open(message, vector.sessionKey), false))
            case "files.complete":
                let payload = try XCTUnwrap(try JSONSerialization.jsonObject(with: try open(message, vector.sessionKey)) as? [String: Any])
                completes[try XCTUnwrap(payload["transferId"] as? String)] = payload["sha256"] as? String
            default:
                break
            }
        }
        XCTAssertEqual(vector.files.count, 2)
        for file in vector.files {
            let name = try XCTUnwrap(file["name"] as? String)
            let offer = try XCTUnwrap(offers.values.first { $0.name == name })
            let parts = try XCTUnwrap(chunks[offer.transferId]).sorted { $0.sequence < $1.sequence }
            XCTAssertTrue(parts.allSatisfy { $0.binary == (file["binary"] as? Bool) }, name)
            XCTAssertEqual(parts.map(\.sequence), Array(0..<Int64(parts.count)))
            let data = parts.reduce(Data()) { $0 + $1.data }
            XCTAssertEqual(data, Data(try XCTUnwrap(file["text"] as? String).utf8))
            XCTAssertEqual(Int64(data.count), offer.size)
            let digest = Data(SHA256.hash(data: data)).base64EncodedString()
            XCTAssertEqual(digest, offer.sha256)
            XCTAssertEqual(completes[offer.transferId], digest)
        }
    }
}
